.xt-text-phonebar, .xt-text-userinfo,
.xt-text-tweet, .xt-text-imgdesc, .xt-text-statline, .xt-text-cmt_all,
.xt-text-musicsong, .xt-text-musiclyric, .xt-text-musicfeel,
.xt-text-douyin_video, .xt-text-douyin_bgm, .xt-text-douyin_caption,
.xt-text-douyin_stats, .xt-text-douyin_cmt,
.xt-text-zhihu_q, .xt-text-zhihu_a,
.xt-text-bili_title, .xt-text-bili_rest, .xt-text-bili_mycmt,
.xt-text-xh_title, .xt-text-xh_rest, .xt-text-xh_mycmt,
.xt-text-game,
.xt-text-album_1, .xt-text-album_2, .xt-text-album_3,
.xt-text-location,
.xt-text-order, .xt-text-delivery, .xt-text-wallet_app,
.xt-text-bills_expense, .xt-text-bills_income,
.xt-text-health_steps, .xt-text-health_sleep,
.xt-text-calendar_note, .xt-text-alarm,
.xt-text-chat_a_title, .xt-text-chat_b_title, .xt-text-chat_g_title,
.xt-text-call, .xt-text-fav,
.xt-text-p1body, .xt-text-p1cmt, .xt-text-p2body, .xt-text-p2cmt,
.xt-text-pollq, .xt-text-pollopt, .xt-text-pollinfo,
.xt-text-trends_hot, .xt-text-trends_view, .xt-text-history,
.xt-text-recommend_reminder,
