  border-bottom: 1px solid rgba(255,255,255,0.07);
}
.xt-text-imgdesc {
  padding: 20px 14px;
  background: linear-gradient(180deg, #1c1c20, #19191d);
  border: 1px solid rgba(201,168,106,0.2);
  border-radius: 12px;
  margin: 10px 0;
  font-size: 13px;
  text-align: center;
  color: rgba(245,245,243,0.7);
}
.xt-text-statline {
