  display: block;
  font-size: 10px; font-weight: 700;
  letter-spacing: 2.4px;
  color: #4ade80;
  margin-bottom: 6px;
}
.xt-row { display: flex; gap: 10px; }
.xt-row > * { flex: 1; }
.xt-ring { margin-bottom: 6px; }
.xt-ring-fill { stroke: #c9a86a; }
