  border: 1px solid rgba(34,197,94,0.2);
  border-left: 3px solid #22c55e;
  border-radius: 12px;
  font-size: 13.5px; line-height: 1.9;
  color: rgba(245,245,243,0.85);
  margin-top: 10px;
}
.xt-text-health_sleep {
  padding: 10px 14px;
  background: #10231a;
  border: 1px solid rgba(34,197,94,0.2);
  border-left: 3px solid #22c55e;
  border-radius: 12px;
  font-size: 13.5px; line-height: 1.9;
  color: rgba(245,245,243,0.85);
  margin-top: 8px;
}
/* 日程与待办：行距加大，一条一行 */
.xt-text-calendar_note {
  padding: 10px 14px 10px 16px;
  background: #1e1e22;
  border: 1px solid rgba(255,255,255,0.07);
  border-left: 3px solid #c9a86a;
  border-radius: 12px;
  font-size: 13.5px; line-height: 2.3;
  color: rgba(245,245,243,0.75);
}
.xt-text-alarm {
  padding: 12px 14px;
  background: #211d16;
  border: 1px solid rgba(201,168,106,0.18);
  border-left: 3px solid #c9a86a;
  border-radius: 12px;
  font-size: 13.5px; line-height: 2.1;
  color: #f5f5f3;
}
/* ===== 第11段 · 微信 ===== */
.xt-text-chat_a_title,
.xt-text-chat_b_title,
.xt-text-chat_g_title {
  text-align: center;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 1px;
  color: #f5f5f3;
  padding: 4px 0 10px;
  margin-bottom: 10px;
  border-bottom: 1px solid rgba(7,193,96,0.35);
}
.xt-bubble,
